
CREATE TABLE `dem_plan` (
                            `id_` int NOT NULL AUTO_INCREMENT,
                            `type` int NOT NULL DEFAULT '0',
                            `idorder` int NOT NULL DEFAULT '0',
                            `x` varchar(4) NOT NULL DEFAULT '0' COMMENT 'позиция',
                            `x_mat` varchar(4) NOT NULL DEFAULT '0' COMMENT 'позиция для материалов',
                            `y` int NOT NULL DEFAULT '0' COMMENT 'поле',
                            `icount` int NOT NULL DEFAULT '0' COMMENT 'количество',
                            `sqr` double NOT NULL DEFAULT '0',
                            `nch` double NOT NULL DEFAULT '0',
                            `color` varchar(255) DEFAULT NULL,
                            `create_date` int NOT NULL DEFAULT '0' COMMENT 'Дата создания',
                            `plan_date` int NOT NULL DEFAULT '0' COMMENT 'Дата планирования',
                            `start_date` int NOT NULL DEFAULT '0' COMMENT 'Дата изготовления',
                            `plan_ed` double NOT NULL DEFAULT '0' COMMENT 'Кол-во план. единиц',
                            `rama_i` float NOT NULL DEFAULT '0',
                            `stvorka_i` float NOT NULL DEFAULT '0',
                            `impost_i` float NOT NULL DEFAULT '0',
                            `ready_part_date` int NOT NULL DEFAULT '0' COMMENT 'частичная дата готовности',
                            `ready_date` int NOT NULL DEFAULT '0' COMMENT 'Дата готовности',
                            `ship_part_date` int NOT NULL DEFAULT '0',
                            `ship_date` int NOT NULL DEFAULT '0',
                            `note` varchar(10) DEFAULT NULL COMMENT 'Примечания',
                            `bMade` binary(1) NOT NULL DEFAULT '0',
                            `kramz_stv_pr` int NOT NULL DEFAULT '0',
                            `kramz_stv_ready` int NOT NULL DEFAULT '0' COMMENT 'Кол-во отсканированных створок лоджии',
                            `kramz_stv_ship` int NOT NULL DEFAULT '0',
                            PRIMARY KEY (`id_`),
                            KEY `plan_date` (`plan_date`),
                            KEY `ready_date` (`ready_date`),
                            KEY `idorder` (`idorder`),
                            KEY `type` (`type`),
                            KEY `x` (`x`),
                            KEY `ready_part_date` (`ready_part_date`),
                            KEY `create_date` (`create_date`),
                            KEY `start_date` (`start_date`),
                            KEY `x_mat` (`x_mat`),
                            KEY `ship_part_date` (`ship_part_date`),
                            KEY `ship_date` (`ship_date`),
                            KEY `y` (`y`),
                            KEY `color` (`color`),
                            KEY `bMade` (`bMade`),
                            KEY `note` (`note`),
                            KEY `icount` (`icount`)
) ENGINE=MyISAM AUTO_INCREMENT=30 DEFAULT CHARSET=cp1251;

